'use client';

import { useRef, useState, useCallback, useEffect } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls, Environment, Grid } from '@react-three/drei';
import { useDesignStore } from '@/lib/store';
import { Room } from './Room';
import { SceneObject } from './SceneObject';
import { Lighting } from './Lighting';
import * as THREE from 'three';

// Camera tracker component
function CameraTracker() {
  const { setCameraPosition } = useDesignStore();
  const { camera } = useThree();
  const lastUpdate = useRef(0);
  const isMounted = useRef(false);
  
  useEffect(() => {
    isMounted.current = true;
    return () => { isMounted.current = false; };
  }, []);
  
  useFrame(() => {
    if (!isMounted.current) return;
    
    const now = Date.now();
    // Throttle updates to every 100ms
    if (now - lastUpdate.current > 100) {
      lastUpdate.current = now;
      // Project camera forward to get spawn point on floor
      const forward = new THREE.Vector3(0, 0, -1);
      forward.applyQuaternion(camera.quaternion);
      forward.y = 0;
      forward.normalize();
      
      const distance = 8; // Spawn distance from camera
      const spawnX = camera.position.x + forward.x * distance;
      const spawnZ = camera.position.z + forward.z * distance;
      
      setCameraPosition({ x: spawnX, z: spawnZ });
    }
  });
  
  return null;
}

export function Scene3D() {
  const { currentDesign, selectedObjectId, selectObject } = useDesignStore();
  const [isDragging, setIsDragging] = useState(false);
  const controlsRef = useRef<any>(null);
  const canvasRef = useRef<HTMLDivElement>(null);

  if (!currentDesign) return null;

  const handleObjectClick = (id: string) => {
    selectObject(id);
  };

  const handleDragStateChange = (dragging: boolean) => {
    setIsDragging(dragging);
    // Disable orbit controls while dragging
    if (controlsRef.current) {
      controlsRef.current.enabled = !dragging;
    }
  };

  // Handle canvas click for deselect
  const handleCanvasClick = useCallback((e: MouseEvent) => {
    // If we get here, no object was clicked (events bubble up)
    if (!isDragging) {
      selectObject(null);
    }
  }, [isDragging, selectObject]);

  return (
    <div
      ref={canvasRef}
      className="w-full h-full bg-gradient-to-b from-gray-900 to-gray-800"
    >
      <Canvas
        camera={{ position: [0, 12, 25], fov: 60 }}
        shadows
        gl={{ antialias: true }}
      >
        <color attach="background" args={['#1a1a2e']} />
        <fog attach="fog" args={['#1a1a2e', 20, 100]} />
        
        <CameraTracker />
        
        <Lighting preset={currentDesign.roomSettings.lightingPreset} />
        
        {/* Invisible background plane for deselect clicks */}
        <mesh
          rotation={[-Math.PI / 2, 0, 0]}
          position={[0, -0.1, 0]}
          onClick={() => !isDragging && selectObject(null)}
        >
          <planeGeometry args={[500, 500]} />
          <meshBasicMaterial visible={false} />
        </mesh>

        <Room
          settings={currentDesign.roomSettings}
          templateId={currentDesign.templateId}
        />

        {currentDesign.objects.map((obj) => (
          <SceneObject
            key={obj.id}
            object={obj}
            isSelected={obj.id === selectedObjectId}
            onClick={() => handleObjectClick(obj.id)}
            onDragStateChange={handleDragStateChange}
          />
        ))}
        
        {/* Grid disabled - using Room's visual grid instead to avoid pointer event interception */}
        
        <OrbitControls
          ref={controlsRef}
          enablePan={true}
          enableZoom={true}
          enableRotate={true}
          minDistance={5}
          maxDistance={60}
          maxPolarAngle={Math.PI / 2 - 0.05}
          // Controls stay enabled unless actively dragging an object
          enabled={!isDragging}
        />
      </Canvas>
    </div>
  );
}
